/* Check cache; if miss → build geographic clay map prompt */
const body = $input.first().json.body;
const destination = (body.destination || '台灣').replace(/市$|縣$/, '');
const spots = (body.spots || []).filter(Boolean).slice(0, 12);
const days = body.days || [];

// Cache key
const rawKey = destination + '|' + spots.join(',');
const cacheKey = 'clay_' + Buffer.from(rawKey).toString('base64').replace(/[^a-zA-Z0-9]/g, '').substring(0, 28);

const staticData = $getWorkflowStaticData('global');
const cachedUrl = staticData[cacheKey];
const cachedTs  = staticData[cacheKey + '_ts'] || 0;
if (cachedUrl && (Date.now() - cachedTs) < 45 * 60 * 1000) {
  return [{ json: { image_url: cachedUrl, cached: true, cache_key: cacheKey } }];
}

// Calculate relative geographic positions from lat/lng
const allSpots = days.flatMap(d => d.spots || []).filter(s => s.lat && s.lng && s.lat > 20 && s.lng > 118);
let geoHint = '';
if (allSpots.length >= 2) {
  const lats = allSpots.map(s => s.lat);
  const lngs = allSpots.map(s => s.lng);
  const minLat = Math.min(...lats), maxLat = Math.max(...lats);
  const minLng = Math.min(...lngs), maxLng = Math.max(...lngs);
  const latR = maxLat - minLat || 0.01, lngR = maxLng - minLng || 0.01;
  const pos = allSpots.map(s => {
    const v = (s.lat - minLat) / latR;
    const h = (s.lng - minLng) / lngR;
    const vp = v > 0.65 ? 'top' : v > 0.35 ? 'middle' : 'bottom';
    const hp = h > 0.65 ? 'right' : h > 0.35 ? 'center' : 'left';
    return `${s.name} placed at map ${vp}-${hp}`;
  });
  geoHint = 'Accurate geographic placement: ' + pos.join('; ') + '. ';
}

// Day route descriptions
const DAY_COLORS = ['orange', 'blue', 'green', 'purple'];
let routeDesc = '';
if (days.length > 0) {
  routeDesc = days.map(d => {
    const color = DAY_COLORS[(d.day - 1) % DAY_COLORS.length];
    const names = (d.spots || []).map(s => s.name).join(', ');
    return `Day ${d.day} (${color} road): ${names}`;
  }).join(' | ');
} else {
  routeDesc = spots.slice(0, 8).join(', ');
}

const prompt = [
  `3D clay art miniature diorama TOURIST MAP of ${destination}, Taiwan.`,
  'Bird-eye isometric view. Green clay grass terrain base with hills.',
  'Brown clay winding roads and dotted paths connecting all attractions.',
  `Attractions placed as 3D clay miniature buildings and landmarks: ${routeDesc}.`,
  geoHint,
  'Color-coded travel routes: Day 1 = orange dotted path with small orange flags, Day 2 = blue dotted path with blue flags.',
  'Each attraction has a small brown wooden signpost with its name in Chinese characters.',
  'Decorative compass rose in bottom-left corner.',
  `Cute clay title banner at top reading "${destination}旅遊地圖".`,
  'Style: ultra-detailed clay and plasticine texture, fingerprint marks visible, pastel warm colors,',
  'soft studio lighting, kawaii cartoon aesthetic, kid-friendly, highly detailed miniature diorama scale,',
  'similar to Taiwan Tourism Bureau clay map style.'
].filter(Boolean).join(' ');

return [{ json: { image_url: null, cached: false, cache_key: cacheKey, prompt } }];

const item = $input.first().json;
const cacheKey = $('Cache Check').first().json.cache_key;

const d = item.data?.[0];
let imageUrl = d?.url || null;
if (!imageUrl && d?.b64_json) {
  imageUrl = 'data:image/png;base64,' + d.b64_json;
}
if (!imageUrl) throw new Error('No image returned. Response: ' + JSON.stringify(item));

const staticData = $getWorkflowStaticData('global');
const keys = Object.keys(staticData).filter(k => k.startsWith('clay_') && !k.endsWith('_ts'));
if (keys.length >= 15) {
  let oldest = keys[0], oldestTs = staticData[keys[0] + '_ts'] || 0;
  keys.forEach(k => { const t = staticData[k + '_ts'] || 0; if (t < oldestTs) { oldest = k; oldestTs = t; } });
  delete staticData[oldest];
  delete staticData[oldest + '_ts'];
}
if (d?.url) {
  staticData[cacheKey] = imageUrl;
  staticData[cacheKey + '_ts'] = Date.now();
}

return [{ json: { image_url: imageUrl, cached: false } }];
